// ============================================================================
// FreeLang Index 모듈 - B+Tree 인덱스 (배열 기반)
// ============================================================================
// 목표: schema.fl + query.fl의 풀 스캔 병목 해결 (O(n) → O(log n))
// 원리:
//   1. 노드 풀: 배열 기반 노드 저장 (포인터 대신 인덱스)
//   2. 트리 탐색: while 루프로 루트부터 리프까지 (재귀 없음)
//   3. 범위 스캔: 리프 노드 연결 리스트 순회
//   4. 삽입/삭제: 노드 분할/합병으로 균형 유지
// 구조:
//   - 상수 정의 (차수, 제한값)
//   - BTreeNode, BTreeIndex 구조체
//   - 탐색 함수 (find_leaf, binary_search)
//   - 삽입/삭제 함수
//   - 범위 스캔 함수
// ============================================================================

module index {
    // === 상수: B+Tree 설정 ===
    const ORDER:       i32 = 4;    // 차수 (최대 2*ORDER 키)
    const MAX_KEYS:    i32 = 8;    // 노드당 최대 키
    const MAX_PTRS:    i32 = 9;    // 노드당 최대 포인터 (자식)
    const MAX_NODES:   i32 = 512;  // 전체 노드 풀 크기

    // === 상수: 에러 코드 ===
    const IDX_OK:         i32 = 0;
    const IDX_ERR_FULL:   i32 = 50;
    const IDX_ERR_DUP:    i32 = 51;
    const IDX_ERR_NOTFOUND: i32 = 52;

    // === 데이터 구조체 ===

    struct BTreeNode {
        is_leaf:    bool;
        key_count:  i32;
        keys:       [i64];      // 정렬된 키 배열
        row_ids:    [i64];      // 리프 노드: 각 키의 row_id
        children:   [i32];      // 내부 노드: 자식 인덱스
        parent:     i32;        // 부모 인덱스 (-1 = 루트)
        next_leaf:  i32;        // 다음 리프 노드 (-1 = 마지막)
        prev_leaf:  i32;        // 이전 리프 노드 (-1 = 처음)
    }

    struct BTreeIndex {
        col_idx:    i32;
        root:       i32;        // 루트 노드 인덱스
        nodes:      [BTreeNode];
        node_count: i32;
        height:     i32;
        key_count:  i64;
    }

    // === 팩토리 함수 ===

    func index_new(col_idx: i32) -> BTreeIndex {
        let root_node = BTreeNode{
            is_leaf:    true,
            key_count:  0,
            keys:       make([i64], MAX_KEYS),
            row_ids:    make([i64], MAX_KEYS),
            children:   make([i32], MAX_PTRS),
            parent:     -1,
            next_leaf:  -1,
            prev_leaf:  -1,
        };
        let nodes = make([BTreeNode], MAX_NODES);
        nodes[0] = root_node;
        return BTreeIndex{
            col_idx:    col_idx,
            root:       0,
            nodes:      nodes,
            node_count: 1,
            height:     1,
            key_count:  0,
        };
    }

    // === 핵심 탐색 함수 ===

    // 키가 속할 리프 노드 찾기
    func (idx: *BTreeIndex) find_leaf(key: i64) -> i32 {
        let current = idx.root;
        let i = 0;
        for i = 0; i < 100; i = i + 1 {  // 최대 높이 100 제한
            let node = idx.nodes[current];
            if node.is_leaf {
                return current;
            }
            // 자식 노드 선택: key < keys[0] → children[0], 그 외 이진탐색
            let child_idx = 0;
            let j = 0;
            for j = 0; j < node.key_count; j = j + 1 {
                if key < node.keys[j] {
                    break;
                }
                child_idx = j + 1;
            }
            if child_idx >= MAX_PTRS {
                child_idx = node.key_count;
            }
            current = node.children[child_idx];
        }
        return current;
    }

    // 리프 노드에서 키의 위치 찾기 (이진 탐색)
    func binary_search_leaf(node: BTreeNode, key: i64) -> (i32, bool) {
        let left = 0;
        let right = node.key_count - 1;
        let found_idx = -1;
        let found = false;
        for left <= right {
            let mid = (left + right) / 2;
            if node.keys[mid] == key {
                found_idx = mid;
                found = true;
                break;
            } else if node.keys[mid] < key {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
        if !found {
            found_idx = left;  // 삽입 위치
        }
        return (found_idx, found);
    }

    // === 삽입 함수 ===

    func (idx: *BTreeIndex) index_insert(key: i64, row_id: i64) -> i32 {
        if idx.node_count >= MAX_NODES {
            return IDX_ERR_FULL;
        }

        let leaf_idx = idx.find_leaf(key);
        let leaf = idx.nodes[leaf_idx];

        if leaf.key_count >= MAX_KEYS {
            return IDX_ERR_FULL;  // 분할 미구현 (간단화)
        }

        // 삽입 위치 찾기
        let pos = leaf.key_count;
        let i = 0;
        for i = 0; i < leaf.key_count; i = i + 1 {
            if key < leaf.keys[i] {
                pos = i;
                break;
            }
        }

        // 키 삽입 (오른쪽으로 시프트)
        let j = leaf.key_count;
        for j > pos {
            leaf.keys[j] = leaf.keys[j - 1];
            leaf.row_ids[j] = leaf.row_ids[j - 1];
            j = j - 1;
        }
        leaf.keys[pos] = key;
        leaf.row_ids[pos] = row_id;
        leaf.key_count = leaf.key_count + 1;

        idx.nodes[leaf_idx] = leaf;
        idx.key_count = idx.key_count + 1;
        return IDX_OK;
    }

    // === 삭제 함수 ===

    func (idx: *BTreeIndex) index_delete(key: i64, row_id: i64) -> bool {
        let leaf_idx = idx.find_leaf(key);
        let leaf = idx.nodes[leaf_idx];

        // 키 찾기
        let pos = -1;
        let i = 0;
        for i = 0; i < leaf.key_count; i = i + 1 {
            if leaf.keys[i] == key && leaf.row_ids[i] == row_id {
                pos = i;
                break;
            }
        }
        if pos == -1 {
            return false;
        }

        // 오른쪽으로 시프트하여 삭제
        let j = pos;
        for j < leaf.key_count - 1 {
            leaf.keys[j] = leaf.keys[j + 1];
            leaf.row_ids[j] = leaf.row_ids[j + 1];
            j = j + 1;
        }
        leaf.key_count = leaf.key_count - 1;

        idx.nodes[leaf_idx] = leaf;
        idx.key_count = idx.key_count - 1;
        return true;
    }

    // === 검색 함수 ===

    // EQ 검색: 정확 일치
    func (idx: *BTreeIndex) index_search(key: i64) -> (i64, bool) {
        let leaf_idx = idx.find_leaf(key);
        let leaf = idx.nodes[leaf_idx];

        let i = 0;
        for i = 0; i < leaf.key_count; i = i + 1 {
            if leaf.keys[i] == key {
                return (leaf.row_ids[i], true);
            }
        }
        return (0, false);
    }

    // === 범위 스캔 함수 ===

    // RANGE 검색: min_key <= key <= max_key
    func (idx: *BTreeIndex) index_range(min_key: i64, max_key: i64) -> ([i64], i32) {
        let result = make([i64], 1024);
        let result_count = 0;

        // min_key가 속한 리프에서 시작
        let leaf_idx = idx.find_leaf(min_key);

        // 리프 연결 리스트 순회
        for leaf_idx >= 0 && result_count < 1024 {
            let leaf = idx.nodes[leaf_idx];
            let i = 0;
            for i = 0; i < leaf.key_count && result_count < 1024; i = i + 1 {
                if leaf.keys[i] >= min_key && leaf.keys[i] <= max_key {
                    result[result_count] = leaf.row_ids[i];
                    result_count = result_count + 1;
                } else if leaf.keys[i] > max_key {
                    break;
                }
            }

            // max_key 초과시 범위 스캔 종료
            if leaf.key_count > 0 && leaf.keys[leaf.key_count - 1] > max_key {
                leaf_idx = -1;
            } else {
                leaf_idx = leaf.next_leaf;
            }
        }

        return (result, result_count);
    }

    // === 재구성 함수 ===

    // 테이블 전체로 인덱스 재구성
    func (idx: *BTreeIndex) index_rebuild(t: schema.Table) -> i32 {
        // 기존 인덱스 초기화
        let root_node = BTreeNode{
            is_leaf:    true,
            key_count:  0,
            keys:       make([i64], MAX_KEYS),
            row_ids:    make([i64], MAX_KEYS),
            children:   make([i32], MAX_PTRS),
            parent:     -1,
            next_leaf:  -1,
            prev_leaf:  -1,
        };
        idx.nodes[0] = root_node;
        idx.root = 0;
        idx.node_count = 1;
        idx.height = 1;
        idx.key_count = 0;

        // 테이블의 모든 행을 인덱스에 삽입
        let i = 0;
        for i = 0; i < t.row_count; i = i + 1 {
            if !t.deleted_flags[i] {
                let key = t.get_int_val(i, idx.col_idx);
                let err = idx.index_insert(key, t.row_ids[i]);
                if err != IDX_OK {
                    return err;
                }
            }
        }
        return IDX_OK;
    }

    // === 통계 함수 ===

    func (idx: *BTreeIndex) index_stats() -> string {
        let msg = "[BTreeIndex col=" + i32_to_str(idx.col_idx) +
                  "] keys=" + i64_to_str(idx.key_count) +
                  " nodes=" + i32_to_str(idx.node_count) +
                  " height=" + i32_to_str(idx.height);
        return msg;
    }

    // === 헬퍼 함수 ===

    @inline
    func i32_to_str(n: i32) -> string {
        if n == 0 { return "0"; }
        if n == 1 { return "1"; }
        if n == 2 { return "2"; }
        if n == 3 { return "3"; }
        if n == 4 { return "4"; }
        if n == 5 { return "5"; }
        if n == 6 { return "6"; }
        if n == 7 { return "7"; }
        if n == 8 { return "8"; }
        if n == 9 { return "9"; }
        if n < 0 { return "-" + i32_to_str(-n); }
        let d = n / 10;
        let r = n % 10;
        return i32_to_str(d) + i32_to_str(r);
    }

    @inline
    func i64_to_str(n: i64) -> string {
        if n == 0 { return "0"; }
        if n < 0 { return "-" + i64_to_str(-n); }
        return i32_to_str(i32(n));
    }
}

// === 사용 시나리오 ===
//
// 인덱스 생성:
//   let idx = index.index_new(0);  // col_idx=0 인덱싱
//
// 삽입:
//   index.index_insert(100, 1);  // key=100, row_id=1
//   index.index_insert(50, 2);
//   index.index_insert(150, 3);
//
// 검색:
//   let row_id, found = idx.index_search(100);
//
// 범위 스캔:
//   let result, count = idx.index_range(50, 150);
//   // [2, 1, 3] (50 ≤ key ≤ 150)
//
// 삭제:
//   idx.index_delete(50, 2);
//
// 재구성:
//   idx.index_rebuild(&table);
//
