            key_count:  0,
            keys:       make([i64], MAX_KEYS),
            row_ids:    make([i64], MAX_KEYS),
            children:   make([i32], MAX_PTRS),
            parent:     -1,
            next_leaf:  -1,
            prev_leaf:  -1,
        };
        idx.nodes[0] = root_node;
        idx.root = 0;
        idx.node_count = 1;
        idx.height = 1;
        idx.key_count = 0;

        // 테이블의 모든 행을 인덱스에 삽입
        let i = 0;
        for i = 0; i < t.row_count; i = i + 1 {
            if !t.deleted_flags[i] {
                let key = t.get_int_val(i, idx.col_idx);
                let err = idx.index_insert(key, t.row_ids[i]);
                if err != IDX_OK {
                    return err;
                }
            }
        }
        return IDX_OK;
    }

    // === 통계 함수 ===

    func (idx: *BTreeIndex) index_stats() -> string {
        let msg = "[BTreeIndex col=" + i32_to_str(idx.col_idx) +
                  "] keys=" + i64_to_str(idx.key_count) +
                  " nodes=" + i32_to_str(idx.node_count) +
                  " height=" + i32_to_str(idx.height);
        return msg;
    }

    // === 헬퍼 함수 ===

    @inline
    func i32_to_str(n: i32) -> string {
        if n == 0 { return "0"; }
        if n == 1 { return "1"; }
        if n == 2 { return "2"; }
        if n == 3 { return "3"; }
        if n == 4 { return "4"; }
        if n == 5 { return "5"; }
        if n == 6 { return "6"; }
        if n == 7 { return "7"; }
        if n == 8 { return "8"; }
        if n == 9 { return "9"; }
        if n < 0 { return "-" + i32_to_str(-n); }
        let d = n / 10;
        let r = n % 10;
        return i32_to_str(d) + i32_to_str(r);
    }

    @inline
    func i64_to_str(n: i64) -> string {
        if n == 0 { return "0"; }
        if n < 0 { return "-" + i64_to_str(-n); }
        return i32_to_str(i32(n));
    }
}

